            uint256 rand = uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, candidate))) % 2;
            if (rand == 0) {
                player = candidate;
                break;
            }
        }

        vm.deal(player, 10 ether);
        vm.prank(player);
        c.play{value: 10}();

        // After a winning play, the reference sends FEE_AMOUNT to bank.
        // The mutant sends it to the winner, so bank balance becomes 0.
        assertTrue(c.bank.balance == 1);
    }
}

