pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 playCount) public {
        // Bound to a reasonable range to avoid infinite loops, but wide enough to include win cases.
        playCount = bound(playCount, 1, 20);
        // Give the sender enough Ether for all plays.
        address player = address(0xadd1);
        vm.deal(player, playCount * 10 ether);

        uint256 wins = 0;
        for (uint256 i = 0; i < playCount; i++) {
            vm.prank(player);
            // Reset warp for each call to get different pseudo-random outcomes
            vm.warp(block.timestamp + i);
            try c.play{value: 10}() {
                // If play succeeds (no revert), random was evaluated.
                // We need to check if this was a win (pot reset to 0). Since pot was 10 before the win transfer,
                // after win pot == 0. Reading pot() tells us.
                if (c.pot() == 0) {
                    wins++;
                }
            } catch {
                // Should not happen with correct value, but skip if it does.
            }
        }

        // The bank should hold exactly wins * 1 ether (FEE_AMOUNT).
        // The mutant sends that fee to the winner, so bank balance will be 0 when wins > 0.
        assertTrue(c.bank.balance == wins * 1 ether);
    }
}
